CREATE TABLE organization_change_requests (id TEXT PRIMARY KEY,type TEXT NOT NULL,status TEXT NOT NULL,requester_username TEXT NOT NULL,requester_name TEXT NOT NULL,member_id INTEGER,member_name TEXT NOT NULL DEFAULT '',student_no TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',current_department TEXT NOT NULL DEFAULT '',current_position TEXT NOT NULL DEFAULT '',target_department TEXT NOT NULL DEFAULT '',target_position TEXT NOT NULL DEFAULT '',effective_date TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',handover TEXT NOT NULL DEFAULT '',attachments_json TEXT NOT NULL DEFAULT '[]',organization_opinion TEXT NOT NULL DEFAULT '',presidium_opinion TEXT NOT NULL DEFAULT '',synced_member_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,effective_at TEXT NOT NULL DEFAULT '');
CREATE INDEX idx_organization_changes_status ON organization_change_requests(status,updated_at);
CREATE TABLE organization_change_events (id INTEGER PRIMARY KEY AUTOINCREMENT,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,from_status TEXT NOT NULL,to_status TEXT NOT NULL,actor_name TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_organization_change_events_entity ON organization_change_events(entity_type,entity_id,id);
CREATE TABLE organization_assessment_cycles (id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,start_date TEXT NOT NULL DEFAULT '',end_date TEXT NOT NULL DEFAULT '',scope TEXT NOT NULL DEFAULT '',instructions TEXT NOT NULL DEFAULT '',owner_name TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organization_assessment_records (id INTEGER PRIMARY KEY AUTOINCREMENT,cycle_id TEXT NOT NULL,member_id INTEGER NOT NULL,member_name TEXT NOT NULL,score REAL NOT NULL DEFAULT 0,grade TEXT NOT NULL DEFAULT '',comment TEXT NOT NULL DEFAULT '',improvement TEXT NOT NULL DEFAULT '',entered_by TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(cycle_id,member_id));
CREATE UNIQUE INDEX idx_organization_assessment_record_unique ON organization_assessment_records(cycle_id,member_id);
CREATE TABLE organization_affairs (id TEXT PRIMARY KEY,category TEXT NOT NULL DEFAULT '',title TEXT NOT NULL,status TEXT NOT NULL,owner_name TEXT NOT NULL DEFAULT '',participant_names TEXT NOT NULL DEFAULT '',deadline TEXT NOT NULL DEFAULT '',external_platform TEXT NOT NULL DEFAULT '',external_reference TEXT NOT NULL DEFAULT '',materials TEXT NOT NULL DEFAULT '',result TEXT NOT NULL DEFAULT '',attachments_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,archived_at TEXT NOT NULL DEFAULT '');
CREATE INDEX idx_organization_affairs_status ON organization_affairs(status,deadline);
